#!/usr/bin/env bash
# Generated by pocock-harness init. Do not edit. Re-run init to update.
# Stop and SubagentStop hook. Run the build and the tests. Exit 2 to block on a failure.
# Env: QG_BUILD_CMD, QG_TEST_CMD (or the same keys under "env" in .claude/settings.json),
#      QG_GATE_DISABLE=1 turns the gate off.

warn() { printf '{"systemMessage":"%s"}\n' "$1"; exit 0; }

[ "${QG_GATE_DISABLE:-}" = "1" ] && exit 0
cd "${CLAUDE_PROJECT_DIR:-$PWD}" 2>/dev/null || exit 0
git rev-parse --git-dir >/dev/null 2>&1 || exit 0

# Read the stdin JSON. Use jq when present, else grep.
payload=$(cat)
if command -v jq >/dev/null 2>&1; then
  active=$(printf '%s' "$payload" | jq -r '.stop_hook_active // false' 2>/dev/null)
else
  active=$(printf '%s' "$payload" | grep -o '"stop_hook_active"[[:space:]]*:[[:space:]]*[a-z]*' | sed 's/.*:[[:space:]]*//')
fi

# Config: the environment first, then .claude/settings.json.
if [ -z "${QG_BUILD_CMD:-}${QG_TEST_CMD:-}" ] && [ -f .claude/settings.json ] && command -v jq >/dev/null 2>&1; then
  QG_BUILD_CMD=$(jq -r '.env.QG_BUILD_CMD // empty' .claude/settings.json 2>/dev/null)
  QG_TEST_CMD=$(jq -r '.env.QG_TEST_CMD // empty' .claude/settings.json 2>/dev/null)
fi
[ -z "${QG_BUILD_CMD:-}${QG_TEST_CMD:-}" ] && exit 0

# Base commit: the last green HEAD, else the merge-base with origin/HEAD, else HEAD.
state="$(git rev-parse --git-dir)/pocock-harness"
mkdir -p "$state"
base=$(cat "$state/last-green-commit" 2>/dev/null)
git rev-parse -q --verify "${base:-x}^{commit}" >/dev/null 2>&1 || base=$(git merge-base HEAD origin/HEAD 2>/dev/null)
[ -z "$base" ] && base=HEAD

# Committed and uncommitted changes, outside docs/ and *.md. A rename gives the new path.
uncommitted=$(git status --porcelain -uall | cut -c4- | sed 's/.* -> //' | grep -v -e '^docs/' -e '\.md$')
committed=$(git diff --name-only "$base" HEAD 2>/dev/null | grep -v -e '^docs/' -e '\.md$')
[ -z "$uncommitted$committed" ] && exit 0

# Hash HEAD, the uncommitted diff and the untracked content. Skip when it matches the last green run.
head=$(git rev-parse HEAD 2>/dev/null)
hash=$(
  {
    echo "$head"
    printf '%s\n' "$uncommitted" | while IFS= read -r f; do
      [ -z "$f" ] && continue
      git diff HEAD -- "$f" 2>/dev/null
      if [ -f "$f" ] && ! git ls-files --error-unmatch -- "$f" >/dev/null 2>&1; then
        printf 'untracked %s\n' "$f"
        cat "$f"
      fi
    done
  } | git hash-object --stdin
)
[ "$hash" = "$(cat "$state/last-green" 2>/dev/null)" ] && exit 0

# Run the build, then the tests. Exit code 127 means the command is not found.
stage=""
output=""
if [ -n "${QG_BUILD_CMD:-}" ]; then
  output=$(bash -c "$QG_BUILD_CMD" 2>&1); rc=$?
  [ "$rc" -eq 127 ] && warn "quality-gate: build command not found. Skipped."
  [ "$rc" -ne 0 ] && stage="build"
fi
if [ -z "$stage" ] && [ -n "${QG_TEST_CMD:-}" ]; then
  output=$("$(dirname "$0")/with-test-lock.sh" bash -c "$QG_TEST_CMD" 2>&1); rc=$?
  [ "$rc" -eq 75 ] && warn "quality-gate: test lock busy. Tests not run."
  [ "$rc" -eq 127 ] && warn "quality-gate: tests command not found. Skipped."
  [ "$rc" -ne 0 ] && stage="tests"
fi

if [ -z "$stage" ]; then
  printf '%s\n' "$hash" > "$state/last-green"
  printf '%s\n' "$head" > "$state/last-green-commit"
  exit 0
fi

[ "$active" = "true" ] && warn "quality-gate: $stage failed again. Not blocked. Fix it manually."
{
  echo "quality-gate: $stage failed. Fix the failure before you stop."
  printf '%s\n' "$output" | tail -n 60
} >&2
exit 2
